def feature_explanations(*, language: _typing.Literal['tr', 'en', 'de', 'es'] = "tr") -> list[dict[str, Any]]:
    """Return detached metadata in four languages for every feature, without execution.

    Args:
        language (str): Presentation language: tr/en/de/es; guide languages do not expand other report
            APIs. Default: 'tr'.

    Returns:
        The retained feature explanations value, without recomputing measurements.

    Raises:
        ValueError, TypeError: The existing typed-source, configuration or compatibility contract is
        rejected.
        RuntimeError: A requested native workload fails; inspect retained state before retrying.

    Examples:
        # Caller-supplied values; explicitly requested operations only.
        feature_explanations()

    HYSo Guide: metrics.interpretation
    Offline: hyso docs show metrics.interpretation --lang en
    Open: hyso docs open metrics.interpretation --lang en
    """
    if language not in ("tr", "en", "de", "es"):
        raise ValueError("unsupported_language")
    rows = []
    for spec, row in zip(feature_catalog(), _ROWS):
        name, definition_tr, definition_en, purpose_tr, purpose_en, limit_tr, limit_en, units, guide = row
        if language in _LOCALE_ROWS:
            localized_name, definition, purpose, limit = _LOCALE_ROWS[language][len(rows)]
        else:
            localized_name = name if language == "tr" else spec.name
            definition = definition_tr if language == "tr" else definition_en
            purpose = purpose_tr if language == "tr" else purpose_en
            limit = limit_tr if language == "tr" else limit_en
        rows.append(dict(feature_id=spec.feature_id, name=localized_name,
                         definition=definition, purpose=purpose, units=units, limits=limit,
                         explanations=dict(beginner=definition + " " + purpose,
                                           technical=definition + " " + limit,
                                           expert=limit),
                         dependencies=list(spec.dependencies), requirements=list(spec.requirements),
                         executor_modes=list(spec.executor_modes),
                         guide_url="https://github.com/huseyin-dgn/hyso/blob/feature/hyso-models-next/docs/guides/" + guide + ".md"))
    return rows
